function validarFormatoTOTP(codigo) {
  const limpio = codigo.trim();
  if (!limpio) {
    return { valido: false, error: "El código 2FA es obligatorio" };
  }
  if (!/^\d{6}$/.test(limpio)) {
    return { valido: false, error: "El código TOTP debe tener exactamente 6 dígitos numéricos" };
  }
  return { valido: true };
}

const LOCKOUT_KEY = "colina_admin_login_lockout_v1";
const MAX_INTENTOS_ADMIN = 5;
const BLOQUEO_ADMIN_MS = 5 * 60 * 1e3;
function leerEstadoBloqueoAdmin(nowMs = Date.now()) {
  try {
    const raw = localStorage.getItem(LOCKOUT_KEY);
    if (!raw) return { intentos: 0, bloqueadoHastaMs: 0 };
    const parsed = JSON.parse(raw);
    const intentos = Number(parsed.intentos || 0);
    const bloqueadoHastaMs = Number(parsed.bloqueadoHastaMs || 0);
    if (bloqueadoHastaMs > 0 && nowMs >= bloqueadoHastaMs) {
      localStorage.removeItem(LOCKOUT_KEY);
      return { intentos: 0, bloqueadoHastaMs: 0 };
    }
    return { intentos, bloqueadoHastaMs };
  } catch {
    return { intentos: 0, bloqueadoHastaMs: 0 };
  }
}
function registrarFalloLoginAdmin(nowMs = Date.now()) {
  const actual = leerEstadoBloqueoAdmin(nowMs);
  const intentos = actual.intentos + 1;
  const bloqueadoHastaMs = intentos >= MAX_INTENTOS_ADMIN ? nowMs + BLOQUEO_ADMIN_MS : 0;
  const nuevo = { intentos, bloqueadoHastaMs };
  try {
    localStorage.setItem(LOCKOUT_KEY, JSON.stringify(nuevo));
  } catch {
  }
  return nuevo;
}
function limpiarBloqueoAdmin() {
  try {
    localStorage.removeItem(LOCKOUT_KEY);
  } catch {
  }
}
function traducirErrorAuthAdmin(err) {
  const code = String(err?.code || "");
  switch (code) {
    case "auth/invalid-credential":
    case "auth/wrong-password":
    case "auth/user-not-found":
      return "Correo o contraseña corporativa incorrectos en Firebase Authentication.";
    case "auth/too-many-requests":
      return "Demasiados intentos en Firebase Authentication. Espera unos minutos antes de reintentar.";
    case "auth/network-request-failed":
      return "Sin conexión a internet para validar identidad en Firebase Authentication.";
    case "auth/invalid-verification-code":
    case "auth/code-expired":
      return "El código 2FA (TOTP) es incorrecto o ya expiró. Verifica tu Google Authenticator.";
    case "auth/user-disabled":
      return "Esta cuenta corporativa fue deshabilitada en Firebase Authentication.";
    default:
      return err?.message ? `Error de autenticación: ${err.message}` : "No fue posible verificar la identidad.";
  }
}
async function autenticarAdminConFirebase(auth, email, password, codigoTotp, equipo) {
  const correoLimpio = email.trim().toLowerCase();
  const miembro = equipo.find(
    (m) => m.email.trim().toLowerCase() === correoLimpio && m.estado !== "revocado"
  );
  if (!miembro) {
    return {
      ok: false,
      error: "Acceso denegado: Esta consola es privada y solo admite cuentas autorizadas del equipo."
    };
  }
  if (password.length < 6) {
    return {
      ok: false,
      error: "Ingresa tu contraseña corporativa de Firebase Authentication (mínimo 6 caracteres)."
    };
  }
  const totpLimpio = codigoTotp.replace(/\D/g, "");
  if (totpLimpio.length > 0 && !validarFormatoTOTP(totpLimpio)) {
    return {
      ok: false,
      error: "El código 2FA (TOTP) debe tener exactamente 6 dígitos numéricos."
    };
  }
  try {
    const cred = await signInWithEmailAndPassword(auth, correoLimpio, password);
    const emailVerificado = (cred.user?.email || "").trim().toLowerCase();
    if (emailVerificado !== correoLimpio) {
      await signOut(auth);
      return { ok: false, error: "La identidad devuelta por Firebase no coincide con el correo autorizado." };
    }
    return {
      ok: true,
      rol: miembro.rol,
      email: emailVerificado,
      mfaVerificado: false
    };
  } catch (err) {
    if (err?.code === "auth/multi-factor-auth-required") {
      if (!validarFormatoTOTP(totpLimpio)) {
        return {
          ok: false,
          requiereMfaTotp: true,
          error: "Tu cuenta tiene 2FA activo. Ingresa el código TOTP de 6 dígitos de Google Authenticator."
        };
      }
      try {
        const resolver = getMultiFactorResolver(auth, err);
        const totpHint = resolver.hints.find(
          (h) => h.factorId === TotpMultiFactorGenerator.FACTOR_ID
        );
        if (!totpHint) {
          return {
            ok: false,
            error: "La cuenta requiere un segundo factor distinto a TOTP en Firebase."
          };
        }
        const assertion = TotpMultiFactorGenerator.assertionForSignIn(totpHint.uid, totpLimpio);
        const mfaCred = await resolver.resolveSignIn(assertion);
        return {
          ok: true,
          rol: miembro.rol,
          email: (mfaCred.user?.email || correoLimpio).trim().toLowerCase(),
          mfaVerificado: true
        };
      } catch (mfaErr) {
        return { ok: false, error: traducirErrorAuthAdmin(mfaErr) };
      }
    }
    return { ok: false, error: traducirErrorAuthAdmin(err) };
  }
}

